import hashlib
import json
from logging import getLogger
import os
import shutil
import subprocess
from multiprocessing.pool import ThreadPool
from queue import Empty, Queue
from typing import Callable
from zipfile import ZipFile

import requests
from pydantic import BaseModel, Field, computed_field

from libs.structures.settings import InstallSettings

from .state import AppState, AppStateType

logger = getLogger("Modpack")


class ModrinthIndex(BaseModel):
    game: str
    name: str
    summary: str
    java_args: str = Field(default_factory=lambda: "")

    class ModrinthIndexFile(BaseModel):
        path: str
        downloads: list[str]

        class ModrinthIndexFileHashes(BaseModel):
            sha1: str | None = Field(default_factory=lambda: None)
            sha512: str | None = Field(default_factory=lambda: None)

        hashes: ModrinthIndexFileHashes

        @computed_field
        def filename(self) -> str:
            return os.path.basename(self.path)[0:45]

        @property
        def download(self):
            return self.downloads[0]

    files: list[ModrinthIndexFile]
    dependencies: dict[str, str] | None

    @classmethod
    def from_bytes(cls, _bytes: bytes) -> ModrinthIndex:
        _data = json.loads(_bytes)
        return cls(**_data)


class Modpack(BaseModel):
    class Config:
        arbitrary_types_allowed = True

    zip_file: ZipFile
    modrinth_index: ModrinthIndex
    overrides: list[str]

    @classmethod
    def from_zip(cls, zip_file: ZipFile) -> Modpack:
        file_names: list[str] = [
            i.filename for i in zip_file.filelist if not i.is_dir()
        ]

        assert "modrinth.index.json" in file_names, "Missing Index File"

        modrinth_index = ModrinthIndex.from_bytes(
            zip_file.read("modrinth.index.json")
        )

        overrides = [_fn for _fn in file_names if _fn.startswith("overrides")]
        return cls(
            zip_file=zip_file,
            modrinth_index=modrinth_index,
            overrides=overrides,
        )

    @staticmethod
    def checksum_file(path: str, expected_checksum: str) -> bool:
        if not os.path.isfile(path):
            return False

        hasher = hashlib.sha512()
        with open(path, "rb") as local_file:
            hasher.update(local_file.read())

        calculated_hash = hasher.hexdigest()
        if calculated_hash != expected_checksum:
            logger.warning(f"Download verification failed for {path}.")
            return False
        return True

    @staticmethod
    def download_file(url: str, path: str,
                      checksum512: str | None = None) -> None:

        file_exists = os.path.exists(path)
        has_checksum = checksum512 is not None

        if file_exists and has_checksum and Modpack.checksum_file(path, checksum512):  # noqa: E501
            return

        if file_exists:
            os.remove(path)
        os.makedirs(os.path.dirname(path), exist_ok=True)

        req = requests.get(url, stream=True)
        assert req.status_code == 200, \
            f"Failed to download: HTTP {req.status_code}"

        with open(path, "wb") as local_file:
            for chunk in req.iter_content(chunk_size=1024 * 1024 * 1024):
                if chunk:
                    local_file.write(chunk)

        if has_checksum and not Modpack.checksum_file(path, checksum512):
            return Modpack.download_file(url, path, checksum512)

    @computed_field
    def dot_minecraft(self) -> str:
        if os.name == "nt":
            return f"{os.environ['appdata']}/.minecraft"
        else:
            return f"{os.environ['HOME']}/.minecraft"

    @computed_field
    def tmp_path(self) -> str:
        if os.name == "nt":
            return f"{os.environ['TMP']}/modpack_installer"
        return "/tmp/modpack_installer"

    def download_resource(self, file: ModrinthIndex.ModrinthIndexFile):
        self.download_file(
            file.download,
            f"{self.dot_minecraft}/{file.path}",
            file.hashes.sha512,
        )
        return f"{self.dot_minecraft}/{file.path}"

    def install_client(self, installation_settings: InstallSettings):
        filenames = [
            i.path.replace('mods/', '')
            for i in self.modrinth_index.files
        ]

        for file in os.listdir(f'{self.dot_minecraft}/mods'):
            yield AppState(type=AppStateType.DIFF_CHECK, meta=file)
            if file not in filenames:
                logger.info(f"Removing {file}")
                try:
                    os.remove(f'{self.dot_minecraft}/mods/{file}')
                except OSError:
                    logger.warning(f"Failed removing {file}")
        # Extract overrides

        yield AppState(type=AppStateType.OVERRIDES_EXTRACTING)  # pyright: ignore[reportCallIssue] # noqa: E501
        for override in self.overrides:
            self.zip_file.extract(override, self.dot_minecraft)  # pyright: ignore[reportArgumentType] # noqa: E501

        def recursive_move(origin: str, destination: str):
            # Move if it's a file
            if os.path.isdir(origin) and not os.path.exists(destination):
                os.mkdir(destination)

            if os.path.isfile(origin):
                if os.path.exists(destination):
                    os.remove(destination)
                shutil.copy(origin, destination)
                return

            for file in os.listdir(origin):
                recursive_move(origin + f"/{file}", destination + f"/{file}")

        recursive_move(f"{self.dot_minecraft}/overrides/", self.dot_minecraft)  # pyright: ignore[reportArgumentType] # noqa: E501

        shutil.rmtree(f"{self.dot_minecraft}/overrides")

        # Download CDN mods
        queue: Queue[AppState] = Queue()
        download_queue_wrapper: Callable[[ModrinthIndex.ModrinthIndexFile], tuple[None, str]] = lambda file: (  # noqa: 501
            queue.put(
                AppState(type=AppStateType.MODPACK_DOWNLOADING, meta=file)
            ),
            self.download_resource(file),
        )

        executor = ThreadPool(16)
        future = executor.map_async(
            download_queue_wrapper,
            self.modrinth_index.files
        )

        while not future.ready():
            try:
                state = queue.get(block=False)
                yield state
            except Empty:
                continue

        # Install NeoForge
        assert self.modrinth_index.dependencies
        neoforge_version = self.modrinth_index.dependencies["neoforge"]
        yield AppState(
            type=AppStateType.LOADER_DOWNLOAD,
            meta=f"Neoforge {neoforge_version}",
        )

        if not os.path.exists(f"{self.tmp_path}"):
            os.mkdir(f"{self.tmp_path}")

        with open(f"{self.dot_minecraft}/launcher_profiles.json", "rb") as file:  # noqa: 501
            launcher_prof = json.load(file)

        if launcher_prof["profiles"]\
                .get("OuchQueDificil", {})\
                .get("lastVersionId") != f"neoforge-{neoforge_version}":

            self.download_file(
                f"https://aiquedificil.com.br/modpack/neoforge-{neoforge_version}-installer-fat.jar",  # noqa: 501
                # f'https://maven.neoforged.net/releases/net/neoforged/neoforge/{neoforge_version}/neoforge-{neoforge_version}-installer.jar',
                f"{self.tmp_path}/neoforge.jar",
            )

            yield AppState(
                type=AppStateType.LOADER_INSTALL
            )  # pyright: ignore[reportCallIssue]

            subprocess.call(
                [
                    "java",
                    "-jar",
                    f"{self.tmp_path}/neoforge.jar",
                    "--install-client"
                ]
            )

        # Prioritize Ouch's profile
        for profile in launcher_prof["profiles"].values():
            profile["lastUsed"] = "1970-01-02T00:00:00.000Z"

        launcher_prof["profiles"]["OuchQueDificil"] = {
            "icon": "data:image/png;base64,",  # noqa: 501
            "lastUsed": "2025-11-23T01:27:22.178Z",
            "lastVersionId": f"neoforge-{neoforge_version}",
            "name": "Ouch Que Dificil",
            # TODO: Implement dynamic GC
            "javaArgs": f"-Xmx{installation_settings.allocated_memory}M -Xms{installation_settings.allocated_memory}M -XX:+UnlockExperimentalVMOptions -XX:+UseG1GC -XX:G1NewSizePercent=20 -XX:G1ReservePercent=20 -XX:MaxGCPauseMillis=50 -XX:G1HeapRegionSize=32M",  # noqa: 501
            "type": "custom",
        }

        with open(f"{self.dot_minecraft}/launcher_profiles.json", "w") as file:  # noqa: 501
            json.dump(launcher_prof, file, indent=2)

        yield AppState(
            type=AppStateType.DONE
        )  # pyright: ignore[reportCallIssue]
